use std::fs;
use std::path::Path;
use std::path::PathBuf;

use serde_json::Value;
use serde_json::json;
use sha2::Digest;
use sha2::Sha256;

use crate::CliError;
use crate::command::ConsumerInitRequest;
use crate::config::CONFIG_FILENAME;
use crate::installer::CONSUMER_BOOTSTRAP_ASSET;

const GENERATED_FILE_HEADER: &str =
    "# Generated by sc-lint; user edits are preserved by future init runs.\n";
const LEGACY_GENERATED_FILE_HEADER: &str =
    "# Managed by sc-lint; regenerate with `sc-lint init --just`.\n";
const CURRENT_CONFIG_ADDED_COMMENTS: &str = concat!(
    "# User-owned configuration: edit lint/test steps as needed; `sc-lint init --just`\n",
    "# refreshes only missing files and generated version-only updates.\n",
);
const KNOWN_PRIOR_RELEASE_BOOTSTRAP_SHA256: &[&str] =
    &["5e26b4ab0d8fafbe856a94089d3b575b10164258776c4c5c828fecd9802a76db"];
const CONSUMER_JUSTFILE_ASSET: &str = include_str!("../assets/consumer-Justfile");
const CANONICAL_CONSUMER_CONFIG_ASSET: &str = include_str!("../assets/consumer-config.toml");
const CONFIG_VERSION_TOKEN: &str = "{{SC_LINT_VERSION}}";
pub(crate) const BINARY_NOT_FOUND_RECOVERY: &str = "Run `just setup` (or your repository's sc-lint installer) to create or repair a compatible installation.";
pub(crate) const DOCS_SETUP_REFERENCE: &str = "sc-lint docs setup";

/// The classified ownership state of one product-managed consumer file.
/// Generated configurations with only a version change are safe to refresh;
/// all other drift stays user-owned and is never overwritten.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ManagedFileState {
    Current,
    Missing,
    RefreshableGenerated,
    RefreshablePriorRelease,
    UserModified,
}

#[expect(
    clippy::result_large_err,
    reason = "Consumer initialization preserves the shared top-level CliError contract."
)]
pub(crate) fn run_consumer_init(request: ConsumerInitRequest) -> Result<Value, CliError> {
    let root = std::env::current_dir().map_err(|error| {
        CliError::config("failed to read current directory for consumer initialization")
            .with_source(error)
            .with_suggested_action(
                "Change to the consumer repository and rerun `sc-lint init --just`.",
            )
            .with_documentation(DOCS_SETUP_REFERENCE)
    })?;
    run_consumer_init_at(&root, request)
}

#[expect(
    clippy::result_large_err,
    reason = "Consumer integration file ownership errors use the shared top-level CliError contract."
)]
pub(crate) fn run_consumer_init_at(
    root: &Path,
    request: ConsumerInitRequest,
) -> Result<Value, CliError> {
    validate_consumer_init_request(request)?;

    let files = consumer_integration_files(root);
    let mut preserved = Vec::new();
    let mut missing = Vec::new();
    let mut refresh = Vec::new();
    let mut version_only_stale = Vec::new();
    let mut conflicts = Vec::new();
    for file in &files {
        match classify_file(file)? {
            ManagedFileState::Current => preserved.push(file.path.clone()),
            ManagedFileState::Missing => missing.push(file.path.clone()),
            ManagedFileState::RefreshableGenerated => {
                preserved.push(file.path.clone());
                version_only_stale.push(file.path.clone());
            }
            ManagedFileState::RefreshablePriorRelease => {
                refresh.push(file.path.clone());
                version_only_stale.push(file.path.clone());
            }
            ManagedFileState::UserModified => conflicts.push(file.path.clone()),
        }
    }
    let write_needed = missing;
    if !conflicts.is_empty() {
        return Err(CliError::config("consumer integration contains user-owned file conflicts")
            .with_code("CLI.SC_LINT_INTEGRATION_CONFLICT")
            .with_detail("conflicts", paths_to_json(&conflicts))
            .with_cause("one or more product-managed paths differ from the canonical integration" )
            .with_suggested_action(
                "Move or remove the conflicting file, then rerun `sc-lint init --just`; sc-lint will not overwrite it.",
            )
            .with_documentation(DOCS_SETUP_REFERENCE));
    }
    if request.check && (!write_needed.is_empty() || !refresh.is_empty()) {
        let mut outdated = write_needed.clone();
        outdated.extend(refresh.iter().cloned());
        return Err(CliError::config("consumer integration is not current")
            .with_code("CLI.SC_LINT_INTEGRATION_OUTDATED")
            .with_detail("outdated", paths_to_json(&outdated))
            .with_cause(
                "one or more product-managed integration files are missing or from a prior release",
            )
            .with_suggested_action(
                "Run `sc-lint init --just` to create or refresh the managed files.",
            )
            .with_documentation(DOCS_SETUP_REFERENCE));
    }
    if !request.check && !request.dry_run {
        for file in &files {
            if write_needed.contains(&file.path) || refresh.contains(&file.path) {
                if let Some(parent) = file.path.parent() {
                    fs::create_dir_all(parent).map_err(|error| {
                        CliError::config(format!(
                            "failed to create consumer integration directory `{}`",
                            parent.display()
                        ))
                        .with_source(error)
                        .with_suggested_action(
                            "Check directory permissions, then rerun `sc-lint init --just`.",
                        )
                        .with_documentation(DOCS_SETUP_REFERENCE)
                    })?;
                }
                fs::write(&file.path, &file.contents).map_err(|error| {
                    CliError::config(format!(
                        "failed to write consumer integration file `{}`",
                        file.path.display()
                    ))
                    .with_source(error)
                    .with_suggested_action(
                        "Check file permissions, then rerun `sc-lint init --just`.",
                    )
                    .with_documentation(DOCS_SETUP_REFERENCE)
                })?;
            }
        }
    }

    Ok(json!({
        "status": if write_needed.is_empty() { "current" } else if request.dry_run { "would_create" } else { "created" },
        "managed_files": files.iter().map(|file| file.path.display().to_string()).collect::<Vec<_>>(),
        "preserved_files": paths_to_strings(&preserved),
        "created_files": paths_to_strings(&write_needed),
        "version_only_stale_files": paths_to_strings(&version_only_stale),
        "check": request.check,
        "dry_run": request.dry_run,
        "summary": "consumer Just integration is managed by sc-lint",
    }))
}

#[expect(
    clippy::result_large_err,
    reason = "Consumer initialization request validation uses the shared CliError contract."
)]
fn validate_consumer_init_request(request: ConsumerInitRequest) -> Result<(), CliError> {
    if !request.just {
        return Err(CliError::usage("`sc-lint init` requires `--just`")
            .with_suggested_action(
                "Run `sc-lint init --just` to create the canonical consumer integration.",
            )
            .with_documentation(DOCS_SETUP_REFERENCE));
    }
    if request.check && request.dry_run {
        return Err(
            CliError::usage("`--check` and `--dry-run` cannot be combined")
                .with_suggested_action(
                    "Use either `--check` or `--dry-run`, then rerun `sc-lint init --just`.",
                )
                .with_documentation(DOCS_SETUP_REFERENCE),
        );
    }
    Ok(())
}

struct ConsumerIntegrationFile {
    path: PathBuf,
    contents: String,
    kind: ManagedFileKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ManagedFileKind {
    Config,
    Static,
    Bootstrap,
}

fn consumer_integration_files(root: &Path) -> Vec<ConsumerIntegrationFile> {
    vec![
        ConsumerIntegrationFile {
            path: root.join(CONFIG_FILENAME),
            contents: canonical_consumer_config(),
            kind: ManagedFileKind::Config,
        },
        ConsumerIntegrationFile {
            path: root.join("Justfile"),
            contents: format!("{GENERATED_FILE_HEADER}{CONSUMER_JUSTFILE_ASSET}"),
            kind: ManagedFileKind::Static,
        },
        ConsumerIntegrationFile {
            path: root.join(".sc-lint/bootstrap.py"),
            contents: CONSUMER_BOOTSTRAP_ASSET.to_string(),
            kind: ManagedFileKind::Bootstrap,
        },
    ]
}

#[expect(
    clippy::result_large_err,
    reason = "Consumer file inspection returns the shared top-level CliError contract."
)]
fn classify_file(file: &ConsumerIntegrationFile) -> Result<ManagedFileState, CliError> {
    match fs::read_to_string(&file.path) {
        Ok(actual) if normalize_line_endings(&actual) == normalize_line_endings(&file.contents) => {
            Ok(ManagedFileState::Current)
        }
        Ok(actual)
            if file.kind == ManagedFileKind::Config && is_refreshable_generated_config(&actual) =>
        {
            Ok(ManagedFileState::RefreshableGenerated)
        }
        Ok(actual)
            if file.kind == ManagedFileKind::Static && is_legacy_generated_justfile(&actual) =>
        {
            Ok(ManagedFileState::Current)
        }
        Ok(actual)
            if file.kind == ManagedFileKind::Bootstrap
                && is_known_prior_release_bootstrap(&actual) =>
        {
            Ok(ManagedFileState::RefreshablePriorRelease)
        }
        Ok(_) => Ok(ManagedFileState::UserModified),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(ManagedFileState::Missing),
        Err(error) => Err(CliError::config(format!(
            "failed to inspect consumer integration file `{}`",
            file.path.display()
        ))
        .with_source(error)
        .with_suggested_action("Check file permissions, then rerun `sc-lint init --just`.")
        .with_documentation(DOCS_SETUP_REFERENCE)),
    }
}

fn is_refreshable_generated_config(actual: &str) -> bool {
    let actual = normalize_line_endings(actual);
    let body = actual
        .strip_prefix(GENERATED_FILE_HEADER)
        .or_else(|| actual.strip_prefix(LEGACY_GENERATED_FILE_HEADER))
        .unwrap_or_default();
    has_version_only_difference(body, CANONICAL_CONSUMER_CONFIG_ASSET)
        || CANONICAL_CONSUMER_CONFIG_ASSET
            .strip_prefix(CURRENT_CONFIG_ADDED_COMMENTS)
            .is_some_and(|legacy_asset| has_version_only_difference(body, legacy_asset))
}

fn normalize_line_endings(contents: &str) -> String {
    contents.replace("\r\n", "\n")
}

fn is_legacy_generated_justfile(actual: &str) -> bool {
    normalize_line_endings(actual)
        .strip_prefix(LEGACY_GENERATED_FILE_HEADER)
        .is_some_and(|body| body == normalize_line_endings(CONSUMER_JUSTFILE_ASSET))
}

fn is_known_prior_release_bootstrap(actual: &str) -> bool {
    let normalized = normalize_line_endings(actual);
    let digest = format!("{:x}", Sha256::digest(normalized.as_bytes()));
    KNOWN_PRIOR_RELEASE_BOOTSTRAP_SHA256.contains(&digest.as_str())
}

fn has_version_only_difference(actual: &str, template: &str) -> bool {
    let (prefix, suffix) = template
        .split_once(CONFIG_VERSION_TOKEN)
        .expect("consumer config asset must contain its version token");
    actual
        .strip_prefix(prefix)
        .and_then(|remainder| remainder.strip_suffix(suffix))
        .is_some_and(|version| {
            version
                .parse::<crate::compatibility::MinimumVersion>()
                .is_ok()
        })
}

fn canonical_consumer_config() -> String {
    format!(
        "{GENERATED_FILE_HEADER}{}",
        CANONICAL_CONSUMER_CONFIG_ASSET.replace(CONFIG_VERSION_TOKEN, env!("CARGO_PKG_VERSION"))
    )
}

fn paths_to_strings(paths: &[PathBuf]) -> Vec<String> {
    paths
        .iter()
        .map(|path| path.display().to_string())
        .collect()
}

fn paths_to_json(paths: &[PathBuf]) -> Value {
    json!(paths_to_strings(paths))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn generated_config_uses_the_single_canonical_asset() {
        let generated = canonical_consumer_config();
        assert!(generated.starts_with(GENERATED_FILE_HEADER));
        assert_eq!(
            generated.trim_start_matches(GENERATED_FILE_HEADER),
            CANONICAL_CONSUMER_CONFIG_ASSET
                .replace(CONFIG_VERSION_TOKEN, env!("CARGO_PKG_VERSION"))
        );
    }

    #[test]
    fn generated_config_with_only_a_version_difference_is_refreshable() {
        let old = canonical_consumer_config().replace(env!("CARGO_PKG_VERSION"), "0.0.0");
        assert!(is_refreshable_generated_config(&old));
        assert!(!is_refreshable_generated_config(
            "[tool.sc-lint]\nminimum_version = \"0.0.0\"\n"
        ));
    }

    #[test]
    fn generated_files_ignore_crlf_but_not_content_edits() {
        let fixture = tempfile::TempDir::new().expect("fixture");
        let files = consumer_integration_files(fixture.path());
        for file in &files {
            if let Some(parent) = file.path.parent() {
                fs::create_dir_all(parent).expect("managed file parent");
            }
            fs::write(&file.path, to_crlf(&file.contents)).expect("CRLF generated file");
            assert_eq!(
                classify_file(file).expect("classify CRLF generated file"),
                ManagedFileState::Current,
                "{}",
                file.path.display()
            );
        }

        let config = &files[0];
        let stale_config = config.contents.replace(env!("CARGO_PKG_VERSION"), "0.8.4");
        fs::write(&config.path, to_crlf(&stale_config)).expect("CRLF stale config");
        assert_eq!(
            classify_file(config).expect("classify CRLF stale config"),
            ManagedFileState::RefreshableGenerated
        );

        let edited_config =
            stale_config.replace("\"fmt\", \"--all\", \"--check\"", "\"fmt\", \"--all\"");
        fs::write(&config.path, to_crlf(&edited_config)).expect("edited CRLF config");
        assert_eq!(
            classify_file(config).expect("classify edited CRLF config"),
            ManagedFileState::UserModified
        );

        let justfile = &files[1];
        let edited_justfile = justfile
            .contents
            .replace("default: lint", "default: edited");
        fs::write(&justfile.path, to_crlf(&edited_justfile)).expect("edited CRLF Justfile");
        assert_eq!(
            classify_file(justfile).expect("classify edited CRLF Justfile"),
            ManagedFileState::UserModified
        );
    }

    #[test]
    fn literal_0_8_4_generated_config_is_refreshable_but_edited_steps_are_not() {
        const LEGACY_0_8_4_GENERATED_CONFIG: &str = concat!(
            "# Managed by sc-lint; regenerate with `sc-lint init --just`.\n",
            "[tool.sc-lint]\n",
            "minimum_version = \"0.8.4\"\n\n",
            "[[tool.sc-lint.lint]]\n",
            "name = \"fmt\"\n",
            "command = [\"cargo\", \"fmt\", \"--all\", \"--check\"]\n\n",
            "[[tool.sc-lint.lint]]\n",
            "name = \"clippy\"\n",
            "command = [\"cargo\", \"clippy\", \"--workspace\", \"--all-targets\", \"--\", \"-D\", \"warnings\"]\n\n",
            "[[tool.sc-lint.test]]\n",
            "name = \"workspace\"\n",
            "command = [\"cargo\", \"test\", \"--workspace\"]\n",
        );

        let legacy_justfile = include_str!("../tests/fixtures/consumer-Justfile-v0.8.4");
        let legacy_bootstrap = include_str!("../tests/fixtures/consumer-bootstrap-v0.8.4.py");
        for legacy_config in [
            LEGACY_0_8_4_GENERATED_CONFIG.to_owned(),
            to_crlf(LEGACY_0_8_4_GENERATED_CONFIG),
        ] {
            let crlf = legacy_config.contains("\r\n");
            let fixture = tempfile::TempDir::new().expect("fixture");
            let config_path = fixture.path().join(CONFIG_FILENAME);
            fs::write(&config_path, &legacy_config).expect("legacy config");
            let justfile_path = fixture.path().join("Justfile");
            let justfile = if crlf {
                to_crlf(legacy_justfile)
            } else {
                legacy_justfile.to_owned()
            };
            fs::write(&justfile_path, &justfile).expect("legacy Justfile");
            let bootstrap_dir = fixture.path().join(".sc-lint");
            fs::create_dir(&bootstrap_dir).expect("bootstrap directory");
            let bootstrap_path = bootstrap_dir.join("bootstrap.py");
            let bootstrap = if crlf {
                to_crlf(legacy_bootstrap)
            } else {
                legacy_bootstrap.to_owned()
            };
            fs::write(&bootstrap_path, bootstrap).expect("bootstrap");

            let result = run_consumer_init_at(
                fixture.path(),
                ConsumerInitRequest {
                    just: true,
                    check: false,
                    dry_run: false,
                },
            )
            .expect("legacy generated config should be recognized");
            assert_eq!(result["status"], "current");
            assert_eq!(
                result["version_only_stale_files"],
                json!([
                    config_path.display().to_string(),
                    bootstrap_path.display().to_string()
                ])
            );
            assert_eq!(
                fs::read_to_string(&config_path).expect("config remains user-owned"),
                legacy_config
            );
            assert_eq!(
                fs::read_to_string(&bootstrap_path).expect("refreshed bootstrap"),
                CONSUMER_BOOTSTRAP_ASSET
            );

            let edited_justfile = justfile.replace("default: lint", "default: edited");
            fs::write(&justfile_path, &edited_justfile).expect("edited legacy Justfile");
            let error = run_consumer_init_at(
                fixture.path(),
                ConsumerInitRequest {
                    just: true,
                    check: false,
                    dry_run: false,
                },
            )
            .expect_err("edited legacy Justfile remains user-owned");
            assert_eq!(error.code(), "CLI.SC_LINT_INTEGRATION_CONFLICT");
            fs::write(&justfile_path, &justfile).expect("restore legacy Justfile");

            let edited_bootstrap = legacy_bootstrap.replace(
                "#!/usr/bin/env python3\n",
                "#!/usr/bin/env python3\n# user-owned edit\n",
            );
            fs::write(
                &bootstrap_path,
                if crlf {
                    to_crlf(&edited_bootstrap)
                } else {
                    edited_bootstrap
                },
            )
            .expect("edited legacy bootstrap");
            let error = run_consumer_init_at(
                fixture.path(),
                ConsumerInitRequest {
                    just: true,
                    check: false,
                    dry_run: false,
                },
            )
            .expect_err("edited legacy bootstrap remains user-owned");
            assert_eq!(error.code(), "CLI.SC_LINT_INTEGRATION_CONFLICT");

            let edited_steps =
                legacy_config.replace("\"fmt\", \"--all\", \"--check\"", "\"fmt\", \"--all\"");
            assert!(!is_refreshable_generated_config(&edited_steps));
            fs::write(&config_path, &edited_steps).expect("edited legacy config");
            let error = run_consumer_init_at(
                fixture.path(),
                ConsumerInitRequest {
                    just: true,
                    check: false,
                    dry_run: false,
                },
            )
            .expect_err("edited steps remain user-owned");
            assert_eq!(error.code(), "CLI.SC_LINT_INTEGRATION_CONFLICT");
        }
    }

    #[test]
    fn version_token_must_not_contain_inserted_config_fields() {
        let template = CANONICAL_CONSUMER_CONFIG_ASSET.replace(CONFIG_VERSION_TOKEN, "0.8.4");
        let inserted_key = template.replace(
            "minimum_version = \"0.8.4\"\n",
            "minimum_version = \"0.8.4\"\nextra = \"user value\"\n",
        );
        assert!(!has_version_only_difference(
            &inserted_key,
            CANONICAL_CONSUMER_CONFIG_ASSET
        ));
        assert!(!is_refreshable_generated_config(&format!(
            "{LEGACY_GENERATED_FILE_HEADER}{inserted_key}"
        )));
    }

    fn to_crlf(contents: &str) -> String {
        normalize_line_endings(contents).replace('\n', "\r\n")
    }

    #[test]
    fn version_bumped_generated_config_is_current_but_never_overwritten() {
        let fixture = tempfile::TempDir::new().expect("fixture");
        let request = ConsumerInitRequest {
            just: true,
            check: false,
            dry_run: false,
        };
        run_consumer_init_at(fixture.path(), request).expect("initial integration");
        let config_path = fixture.path().join(CONFIG_FILENAME);
        let old = fs::read_to_string(&config_path)
            .expect("generated config")
            .replace(env!("CARGO_PKG_VERSION"), "0.0.0");
        fs::write(&config_path, old).expect("old generated config");

        let expected_bytes = fs::read(&config_path).expect("old generated config bytes");
        let expected_modified = fs::metadata(&config_path)
            .expect("old generated config metadata")
            .modified()
            .expect("old generated config modification time");

        for request in [
            ConsumerInitRequest {
                just: true,
                check: true,
                dry_run: false,
            },
            ConsumerInitRequest {
                just: true,
                check: false,
                dry_run: true,
            },
            request,
        ] {
            let result = run_consumer_init_at(fixture.path(), request)
                .expect("version-only generated config remains current");
            assert_eq!(result["status"], "current");
            assert_eq!(
                result["version_only_stale_files"].as_array().map(Vec::len),
                Some(1)
            );
            assert_eq!(
                fs::read(&config_path).expect("unchanged config bytes"),
                expected_bytes
            );
            assert_eq!(
                fs::metadata(&config_path)
                    .expect("unchanged config metadata")
                    .modified()
                    .expect("unchanged config modification time"),
                expected_modified
            );
        }
    }
}
